select platform name, count(distinct subbarcode) data FROM omics.integrated_mutation_file


		and platform =#{platform}


		and hospital =#{hospital}


		and specimen_type =#{specimen_type}


		and product_name =#{product_name}


		and cancertype =#{cancertype}


		and clinicalremark =#{clinicalremark}


		and pathologicaltype =#{pathologicaltype}


		and gene =#{gene}


		and mutation like '%' #{mutation} '%'


		and fastcode =#{fastcode}

		and analysis_date between #{analysis_date_B} and #{analysis_date_N} 

group by platform order by platform

